def name_existing_racks(apps, schema_editor):
    """Every tablet already on a rack is called "Rack N", N its number, so a gym that
    is already set up looks exactly as before and nobody re-does anything."""
    RackScreen = apps.get_model('event_handler', 'RackScreen')
    for screen in RackScreen.objects.exclude(rack_number=None).filter(name=''):
        screen.name = f'Rack {screen.rack_number}'
        screen.save(update_fields=['name'])


